def maximal_points(T, tests):
	for t in range(T):
		(N, W) = map(int, input().split())
		(C, P, T) = ([], [], [])
		for i in range(N):
			(c, p, t) = map(int, input().split())
			C.append(c)
			P.append(p)
			T.append(t)
		dp = [[0 for j in range(W + 1)] for i in range(N + 1)]
		for i in range(1, N + 1):
			for j in range(1, W + 1):
				if j < T[i - 1]:
					dp[i][j] = dp[i - 1][j]
				else:
					dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - T[i - 1]] + C[i - 1] * P[i - 1])
		print(dp[N][W])
T = int(input())
tests = [0] * T
maximal_points(T, tests)
